engine.fcFindings:
function fcFindings(read) {
  read = read || {};
  var style = read.style || {}, input = read.input || {}, paras = input.paragraphs || [], terms = input.terms || [];
  var CAP = 25, MOST = 0.6, CLIP = 70;
  function clean(s) { return String(s == null ? "" : s).replace(/[\s\u0000-\u001f]+/g, " ").trim(); }
  function clip(s) { s = clean(s); return s.length <= CLIP ? s : s.slice(0, CLIP - 1).replace(/\s+\S*$/, "") + "…"; }
  function around(t, at, len) {   // the words around a place in a paragraph
    var a = Math.max(0, at - 30), b = Math.min(t.length, at + len + 30);
    return (a > 0 ? "…" : "") + clean(t.slice(a, b)) + (b < t.length ? "…" : "");
  }
  var groups = [];
  // [HOUSE-STYLE] each feature's usual way, kept even where the document never departs from it (the summary on top)
  var usual = {};
  // A group from items, each with a value: the usual value (most of them, at least MOST), the rest listed.
  // [FMT-FIX] fixOf(the usual's raw value) → the fix that gives a place the usual look ({ kind: "font" | "para", props }
  // or { kind: "look", look }); none: the group is listed only. A fixable group lists every place (FIX_CAP), each with
  // what to find (at: a term's or a label's words). With no one way holding most of them, the user picks the look: the
  // choices (each with its count and an example) and every place. keep: one way throughout is still said (a quiet card).
  function byMajority(key, title, rows, label, min, fixOf, keep) {
    rows = rows.filter(function (r) { return r.v != null; });
    if (rows.length < (min || 3)) return;
    var n = {}, order = [], raw = {}, ex = {};
    rows.forEach(function (r) { var k = String(r.v); if (!n[k]) { n[k] = 0; order.push(k); raw[k] = r.raw !== undefined ? r.raw : r.v; ex[k] = r.snippet; } n[k]++; });
    var name = function (k) { return label ? label(k) : k; };
    var best = order.slice().sort(function (a, b) { return n[b] - n[a]; })[0];
    if (n[best] / rows.length >= MOST) usual[key] = name(best);
    if (order.length < 2) {
      if (keep) groups.push({ key: key, title: title, usual: name(order[0]), share: 1, count: 0, items: [], fix: null });
      return;
    }
    order.sort(function (a, b) { return n[b] - n[a]; });
    var top = order[0], share = n[top] / rows.length;
    var odd = rows.filter(function (r) { return String(r.v) !== top; });
    var shape = function (r) { var o = { i: r.i, snippet: r.snippet, found: name(String(r.v)), v: String(r.v) }; if (r.at) o.at = r.at; if (r.within) o.within = r.within; if (r.edits) o.edits = r.edits; if (r.x) o.x = r.x; if (r.qe) o.qe = r.qe; return o; };
    // no one way holds most of them: the split, not every place (nothing to measure them against) — unless the user
    // picks the look ([FMT-FIX]: never guessed)
    if (share < MOST) {
      var g = { key: key, title: title, usual: null, share: Math.round(share * 100) / 100, count: 0, items: [],
        split: order.slice(0, 4).map(function (k) { return name(k) + " " + Math.round(n[k] / rows.length * 100) + "%"; }).join(" · ") };
      if (fixOf) {
        g.choices = order.slice(0, 6).map(function (k) { return { v: k, label: name(k), n: n[k], example: ex[k], fix: fixOf(raw[k]) }; });
        g.rows = rows.slice(0, FIX_CAP).map(shape);
      }
      groups.push(g);
      return;
    }
    groups.push({ key: key, title: title, usual: name(top), v: top, share: Math.round(share * 100) / 100, count: odd.length,
      items: odd.slice(0, fixOf ? FIX_CAP : CAP).map(shape), fix: fixOf ? fixOf(raw[top]) : null });
  }
  var FIX_CAP = 300;
  // [FMT-FIX] a look's words ("bold + italic") as the fix that sets it: bold, italic, underline (capitals are wording)
  function fcLookFix(v) {
    v = String(v || "");
    return { kind: "look", look: { bold: /\bbold\b/.test(v), italic: /\bitalic\b/.test(v), underline: /\bunderlined\b/.test(v) ? "Single" : "None" } };
  }
  // A group of places one rule finds (no majority needed: the document's own usual is given).
  function listed(key, title, usual, rows, fix) {
    if (!rows.length) return;
    groups.push({ key: key, title: title, usual: usual, count: rows.length, items: rows.slice(0, fix ? FIX_CAP : CAP), fix: fix || null });
  }
  var heads = {}, labelAt = {};
  (read.labelCandidates || []).forEach(function (c) { labelAt[c.i] = c; if (!c.runIn) heads[c.i] = c; });
  var toc = function (p) { return /^toc\s*\d$/i.test(String(p.styleBuiltIn || "")) || /^toc\s*\d$/i.test(clean(p.style)); };
  // The agreement itself: up to its signature block or its first exhibit — what follows (a project description, a
  // policy) is a document of its own, set its own way. Its look, headings, spacing and numbering are checked there only.
  var end = paras.length;
  for (var e = 10; e < paras.length; e++) {
    if (/^(IN WITNESS WHEREOF|EXHIBIT|APPENDIX|SCHEDULE|ANNEX|ATTACHMENT)\b/i.test(clean(paras[e] && paras[e].text))) { end = e; break; }
  }
  var main = function (i) { return i < end; };
  var body = [];
  paras.forEach(function (p, i) { var t = clean(p && p.text); if (main(i) && t.length >= 40 && !p.inTable && !toc(p) && !heads[i]) body.push({ p: p, i: i, t: t }); });

  // 1. Body text: its font, its size and its alignment, each against the document's usual.
  var size = function (s) { return s == null || s === "" ? null : Math.round(Number(s) * 2) / 2; };
  byMajority("body-font", "Body text in another font", body.map(function (b) { return { i: b.i, v: b.p.font || null, snippet: clip(b.t) }; }), null, 3,
    function (v) { return { kind: "font", props: { name: v } }; });
  byMajority("body-size", "Body text in another size", body.map(function (b) { return { i: b.i, v: size(b.p.sizePt), snippet: clip(b.t) }; }), function (v) { return v + " pt"; }, 3,
    function (v) { return { kind: "font", props: { size: Number(v) } }; });
  // [ALIGN-PROSE] Alignment is measured, and fixed, on prose only (the owner, 10-23: a fix to justified "spaces the sentence
  // out across the whole line"): more than a line of it, not a title in capitals, no manual line break — Word stretches a
  // justified line that ends in one (Shift+Enter), and a one-line paragraph reads the same either way.
  var BREAK = /[\u000b\n]/, broke = function (b) { return BREAK.test(String(b.p.text || "").replace(/\s+$/, "")); };
  var caps = function (t) { var L = t.replace(/[^A-Za-z]/g, ""); return L.length >= 8 && (L.match(/[A-Z]/g) || []).length / L.length > 0.6; };
  byMajority("body-align", "Body text aligned differently", body.filter(function (b) { return b.t.length >= 100 && !broke(b) && !caps(b.t); }).map(function (b) {
    return { i: b.i, v: b.p.align ? String(b.p.align).toLowerCase() : null, raw: b.p.align, snippet: clip(b.t) };
  }), null, 3, function (v) { return { kind: "para", props: { alignment: v } }; });
  // [ALIGN-BREAK] where the body is justified, a paragraph with a manual line break that isn't: listed, never justified
  if (usual["body-align"] === "justified") listed("align-break", "Not justified: a manual line break inside", "justified",
    body.filter(function (b) { return broke(b) && !/^justif/i.test(String(b.p.align || "")); }).map(function (b) {
      return { i: b.i, snippet: clip(b.t), found: b.p.align ? String(b.p.align).toLowerCase() : "not justified" };
    }));

  // 2. Headings: each label's look (bold, italic, underlined, capitals) against the others of its level.
  var looks = {};
  (input.labels || []).forEach(function (x) { if (x && x.i != null) looks[x.i] = x; });
  var lookOf = function (f, label) {
    if (!f || f.bold == null || f.italic == null || f.underline == null) return null;
    var bits = [];
    if (f.bold) bits.push("bold");
    if (f.italic) bits.push("italic");
    if (f.underline && f.underline !== "None") bits.push("underlined");
    var letters = String(label).replace(/[^A-Za-z]/g, "");
    if (letters.length >= 2 && letters === letters.toUpperCase()) bits.push("capitals");
    return bits.length ? bits.join(" + ") : "plain";
  };
  var byGroup = {};
  (read.labelCandidates || []).forEach(function (c) {
    if (!main(c.i)) return;
    var k = String(c.group) + (c.runIn ? " run-in" : "");
    // at: the label's words, not its stop — as doc_style read its look ([LABEL-WORDS])
    (byGroup[k] = byGroup[k] || []).push({ i: c.i, v: lookOf(looks[c.i], c.label), at: c.label.replace(/\s*[.:]$/, "") || c.label, snippet: clip((c.number ? c.number + " " : "") + c.label) });
  });
  Object.keys(byGroup).forEach(function (k) {
    var lv = k.replace(/ run-in$/, ""), name = /^\d+$/.test(lv) ? "level " + lv : "“" + lv + "”";
    byMajority("heading-look-" + k.replace(/\W+/g, "_"), (/run-in$/.test(k) ? "Run-in headings" : "Headings") + " at " + name + " set differently", byGroup[k], null, 3, fcLookFix);
  });

  // 3. Defined terms: their quotes, and their look, against the rest.
  // [TEXT-FIX] a term's own two quote marks (qe: where they are in its paragraph), outside a template field
  var tquote = function (t) {
    var s0 = String((paras[t.i] || {}).text || "").replace(/\{\{[\s\S]*?\}\}|\[\[[\s\S]*?\]\]/g, function (m) { return m.replace(/[^\n]/g, "#"); });
    var k = t.quote === "curly" ? s0.indexOf("“" + t.term + "”") : s0.indexOf("\"" + t.term + "\"");
    return k < 0 ? null : [k, k + String(t.term).length + 1];
  };
  byMajority("term-quotes", "Defined terms in other quotes", terms.map(function (t) { return { i: t.i, v: t.quote || null, qe: tquote(t), snippet: clip(t.snippet || t.term) }; }),
    function (v) { return v === "curly" ? "curly quotes “ ”" : v === "straight" ? "straight quotes \" \"" : v; }, 3,
    function (v) { return v === "curly" || v === "straight" ? { kind: "text", quote: v } : null; });
  var trows = terms.map(function (t) {
    if (t.bold == null && t.italic == null && t.underline == null) return { v: null };
    var bits = [];
    if (t.bold) bits.push("bold");
    if (t.italic) bits.push("italic");
    if (t.underline) bits.push("underlined");
    return { i: t.i, v: bits.join(" + ") || "plain", at: t.term, within: t.quote === "straight" ? "\"" + t.term + "\"" : "“" + t.term + "”", how: t.how, snippet: clip(t.snippet || t.term) };   // within: [TERM-QUOTED] its own quotes
  }).filter(function (r) { return r.v != null; });
  // [TERM-EXHIBITS] terms defined in an exhibit (a data-protection addendum, a project plan) keep that document's own look,
  // against each other — as its fonts and headings are measured apart (Feno: its addendum's terms bold, the agreement's
  // italic — the owner, 10-23: "Sell" and "Share" missed)
  var trowsX = trows.filter(function (r) { return !main(r.i); });
  trows = trows.filter(function (r) { return main(r.i); });
  if (trowsX.length >= 3) byMajority("term-look-exhibits", "Defined terms in the exhibits set differently", trowsX, null, 3, fcLookFix, true);
  // [FMT-FIX] no one look across them: first by where each is defined — a definitions list ("Records" means …) and
  // inline (the "Materials") may each keep a look of its own (two conventions, nothing to fix); each against its own
  // (the owner, 10-22: "plain 50% · italic 33% · bold + italic 8% · underlined 8%")
  var tTop = (function () { var n = {}, best = 0; trows.forEach(function (r) { n[r.v] = (n[r.v] || 0) + 1; best = Math.max(best, n[r.v]); }); return trows.length ? best / trows.length : 1; })();
  var tDefs = trows.filter(function (r) { return r.how === "definitions"; }), tIn = trows.filter(function (r) { return r.how === "inline"; });
  if (tTop < MOST && tDefs.length >= 3 && tIn.length >= 3) {
    byMajority("term-look-definitions", "Defined terms in the definitions set differently", tDefs, null, 3, fcLookFix, true);
    byMajority("term-look-inline", "Defined terms defined in the text set differently", tIn, null, 3, fcLookFix, true);
  } else byMajority("term-look", "Defined terms set differently", trows, null, 3, fcLookFix);

  // [TEXT-FIX] (the owner, 10-23: "anything that says listed only should be fixable") — the text findings below carry each
  // place's changes (characters of its paragraph), written by ELI Writer's textFix; never inside a template field.
  var tokenless = function (t) { return t.replace(/\{\{[\s\S]*?\}\}|\[\[[\s\S]*?\]\]/g, function (m) { return m.replace(/[^\n]/g, "#"); }); };
  var TEXT = { kind: "text" };

  // 4. Quotation marks and apostrophes in the text: curly or straight, the document's way. A straight " opens after a
  // space, a bracket or a dash and closes otherwise; ' is an apostrophe after a letter.
  var qrows = [];
  paras.forEach(function (p, i) {
    var t = String((p && p.text) || ""), s = tokenless(t);
    var cur = (s.match(/[“”‘’]/g) || []).length, st = (s.match(/["']/g) || []).length;
    if (cur || st) qrows.push({ i: i, cur: cur, st: st, t: t, s: s });
  });
  var cTot = 0, sTot = 0;
  qrows.forEach(function (r) { cTot += r.cur; sTot += r.st; });
  var opens = function (s, k) { return k === 0 || /[\s(\[{—–\/]/.test(s.charAt(k - 1)); };
  if (cTot + sTot >= 10) {
    var curlyDoc = cTot >= sTot, share = Math.max(cTot, sTot) / (cTot + sTot);
    if (share >= 0.8) usual.quotes = curlyDoc ? "curly “ ” ’" : "straight \" '";
    if (share >= 0.8) listed("quotes", curlyDoc ? "Straight quotes or apostrophes where the document uses curly ones" : "Curly quotes or apostrophes where the document uses straight ones",
      curlyDoc ? "curly “ ” ’" : "straight \" '", qrows.filter(function (r) { return curlyDoc ? r.st : r.cur; }).map(function (r) {
        var re = curlyDoc ? /["']/g : /[“”‘’]/g, m, edits = [], first = r.s.search(curlyDoc ? /["']/ : /[“”‘’]/);
        while ((m = re.exec(r.s))) {
          var k = m.index, ch = m[0];
          var w = !curlyDoc ? (/[“”]/.test(ch) ? "\"" : "'") : ch === "\"" ? (opens(r.s, k) ? "“" : "”")
            : (opens(r.s, k) && /[A-Za-z]/.test(r.s.charAt(k + 1)) ? "‘" : "’");
          edits.push({ at: k, len: 1, with: w });
        }
        return { i: r.i, snippet: around(r.t, first, 1), found: edits.length + " " + (curlyDoc ? "straight" : "curly"), edits: edits };
      }), TEXT);
  }

  // 5. Dashes between words: a spaced hyphen ("fees - including") where the document uses a dash — written as the
  // document writes its dashes (an en dash with spaces, an em dash with spaces, or an em dash closed up).
  var enS = 0, emS = 0, emC = 0, hy = [];
  paras.forEach(function (p, i) {
    var t = String((p && p.text) || ""), s = tokenless(t), m, edits = [], re = /[\w"”’)\]] - [\w"“(]/g;
    enS += (s.match(/\s–\s/g) || []).length; emS += (s.match(/\s—\s/g) || []).length; emC += (s.match(/\w—\w/g) || []).length;
    while ((m = re.exec(s))) { edits.push(m.index + 1); re.lastIndex = m.index + 3; }
    if (edits.length) hy.push({ i: i, at: edits, snippet: around(t, edits[0] - 1, 5), found: edits.length > 1 ? edits.length + " hyphens as dashes" : "a hyphen as a dash" });
  });
  var dash = enS + emS + emC, dashW = emC > enS + emS ? "—" : emS > enS ? " — " : " – ";
  if (dash >= 3 && dash >= hy.length * 2) {
    usual.dashes = dashW === "—" ? "an em dash, closed up (word—word)" : dashW === " — " ? "an em dash with spaces ( — )" : "an en dash with spaces ( – )";
    listed("dashes", "A hyphen used as a dash", usual.dashes, hy.map(function (r) {
      return { i: r.i, snippet: r.snippet, found: r.found, edits: r.at.map(function (k) { return { at: k, len: 3, with: dashW }; }) };
    }), TEXT);
  }

  // 6. Spaces: two after a full stop in some places, one in others; two between words.
  // [SENT-SPACES] Only the document's own sentences count (the owner, 10-22: "false positives on one space after a full
  // stop where the document uses two"): a template token's text ({{DEF: … }}, [[ … ]]) is guidance, not the document; a
  // run-in heading's stop keeps the headings' own spacing; an abbreviation's stop (Inc., e.g., Mr.) ends no sentence.
  // Masked in place, so a place's offset is still its offset in the paragraph.
  var mask = function (m) { return m.replace(/[^\n]/g, "#"); };
  var ABBR = /\b(?:Inc|Corp|Co|Ltd|Mr|Mrs|Ms|Dr|Jr|Sr|St|vs|cf|viz|approx|e\.g|i\.e)\.(?= )/gi;
  function prose(t, i) {
    t = t.replace(/\{\{[\s\S]*?\}\}|\[\[[\s\S]*?\]\]/g, mask).replace(ABBR, function (m) { return m.slice(0, -1) + "#"; });
    var c = labelAt[i], at = c && c.runIn && c.label ? t.indexOf(c.label) : -1;
    if (at >= 0 && /[.:]$/.test(c.label)) t = t.slice(0, at + c.label.length - 1) + "#" + t.slice(at + c.label.length);
    return t;
  }
  var two = [], one = [], gaps = [], hgap = [];
  paras.forEach(function (p, i) {
    if (!main(i)) return;
    var t = String((p && p.text) || ""), s = prose(t, i);
    // a run-in heading's own gap, against the other headings' (one space after each, or two)
    var c = labelAt[i], at = c && c.runIn && c.label ? t.indexOf(c.label) : -1, sp = at >= 0 ? / +(?=\S)/y : null;
    if (sp) { sp.lastIndex = at + c.label.length; var m = sp.exec(t); if (m) hgap.push({ i: i, v: m[0].length > 1 ? "two spaces" : "one space", gap: [m.index, m[0].length], snippet: around(t, at, c.label.length + 3) }); }
    var a = (s.match(/[a-z)\]”"][.!?]["”’)]? {2}[A-Z(“"]/g) || []).length, b = (s.match(/[a-z)\]”"][.!?]["”’)]? [A-Z(“"]/g) || []).length;
    if (a) two.push({ i: i, n: a, t: t, s: s });
    if (b) one.push({ i: i, n: b, t: t, s: s });
    var ge = [], gm, gre = /[A-Za-z,;]( {2,})(?=[a-z])/g;
    while ((gm = gre.exec(s))) ge.push({ at: gm.index + 1, len: gm[1].length, with: " " });
    if (ge.length) gaps.push({ i: i, snippet: around(t, ge[0].at - 1, ge[0].len + 2), found: ge.length > 1 ? ge.length + " double spaces" : "two spaces between words", edits: ge });
  });
  var twoN = two.reduce(function (s, r) { return s + r.n; }, 0), oneN = one.reduce(function (s, r) { return s + r.n; }, 0);
  if (twoN + oneN >= 10 && Math.max(twoN, oneN) / (twoN + oneN) >= 0.8) usual["sentence-spaces"] = twoN > oneN ? "two spaces" : "one space";
  if (twoN + oneN >= 10 && Math.max(twoN, oneN) / (twoN + oneN) >= 0.8 && Math.min(twoN, oneN) > 0) {
    var twoDoc = twoN > oneN, odd = twoDoc ? one : two;
    var sre = twoDoc ? /([a-z)\]”"][.!?]["”’)]?)( )(?=[A-Z(“"])/g : /([a-z)\]”"][.!?]["”’)]?)( {2})(?=[A-Z(“"])/g;
    listed("sentence-spaces", twoDoc ? "One space after a full stop where the document uses two" : "Two spaces after a full stop where the document uses one",
      twoDoc ? "two spaces" : "one space", odd.map(function (r) {
        var edits = [], m;
        sre.lastIndex = 0;
        while ((m = sre.exec(r.s))) edits.push({ at: m.index + m[1].length, len: m[2].length, with: twoDoc ? "  " : " " });
        return { i: r.i, snippet: around(r.t, edits.length ? Math.max(0, edits[0].at - 3) : 0, 3), found: twoDoc ? "one space" : "two spaces", edits: edits };
      }), TEXT);
  }
  var hTwo = hgap.filter(function (r) { return r.v === "two spaces"; }).length, hOne = hgap.length - hTwo;
  if (hgap.length >= 5 && Math.max(hTwo, hOne) / hgap.length >= 0.8 && Math.min(hTwo, hOne) > 0) {
    var hUsual = hTwo > hOne ? "two spaces" : "one space";
    listed("heading-spaces", hTwo > hOne ? "One space after a heading where the other headings have two" : "Two spaces after a heading where the other headings have one",
      hUsual, hgap.filter(function (r) { return r.v !== hUsual; }).map(function (r) {
        return { i: r.i, snippet: r.snippet, found: r.v, edits: [{ at: r.gap[0], len: r.gap[1], with: hUsual === "two spaces" ? "  " : " " }] };
      }), TEXT);
  }
  listed("word-spaces", "Two spaces between words", "one space", gaps, TEXT);

  // 7. Cross-references: "Section 5.1" against "Clause 5.1" or "§ 5.1" (Article is its own level, never counted). Fixed
  // by their word (Clause → Section, section → Section); a § reference is left as it is.
  var xr = [];
  paras.forEach(function (p, i) {
    var t = String((p && p.text) || ""), s = tokenless(t), m, re = /\b(Section|section|Clause|clause)s?\s+\d{1,3}(?:\.\d{1,3})*|§§?\s?\d{1,3}(?:\.\d{1,3})*/g;
    if (toc(p || {})) return;
    while ((m = re.exec(s))) {
      if (m.index === 0 && labelAt[i]) continue;   // a heading's own number
      // a law's section, not the document's ("Virginia Code §2.2-1837", "15 U.S.C. § 78")
      if (/^§/.test(m[0]) && (/^§§?\s?\d[\d.]*-/.test(t.slice(m.index)) || /\b(Code|U\.\s?S\.\s?C\.?|C\.\s?F\.\s?R\.?|Act|Stat\.?)\s*$/i.test(t.slice(Math.max(0, m.index - 30), m.index)))) continue;
      var w = /^§/.test(m[0]) ? "§" : m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase() + (/^[a-z]/.test(m[1]) ? " (lower case)" : "");
      xr.push({ i: i, v: w, x: /^§/.test(m[0]) ? null : { at: m.index, len: m[1].length }, snippet: around(t, m.index, m[0].length) });
    }
  });
  byMajority("xrefs", "Cross-references written another way", xr, function (v) {
    return v === "§" ? "§ 5.1" : / \(lower case\)$/.test(v) ? v.replace(" (lower case)", "").toLowerCase() + " 5.1" : v + " 5.1";
  }, 5, function (v) { return v === "§" ? null : { kind: "text", word: / \(lower case\)$/.test(v) ? v.replace(" (lower case)", "").toLowerCase() : v }; });

  // 8. Numbering: Word's own list numbers in most numbered paragraphs, typed numbers in a few (or the other way).
