        var go = el("button", "_fc_go"); go.type = "button"; go.title = "Go to it in Word";
        go.appendChild(beforeAfter(x));
        go.appendChild(el("span", "_fc_snip", x.snippet || ""));
        if (x.nofix) go.appendChild(el("span", "_fc_why", x.nofix));
        go.onclick = call("onGo", x.i);
        row.appendChild(go);
        lst.appendChild(row);
      });
      else g.items.forEach(function (x) {
        var row = el("button", "_fc_item _fc_plain"); row.type = "button"; row.title = "Go to it in Word";
        row.appendChild(el("span", "_fc_found", x.found));
        row.appendChild(el("span", "_fc_snip", x.snippet || ""));
        row.onclick = call("onGo", x.i);
        lst.appendChild(row);
      });
      if (!fixable && g.count > g.items.length) lst.appendChild(el("div", "_fc_more", "… and " + (g.count - g.items.length) + " more"));
      card.appendChild(lst);
    }
    // [FC-CATS] each kind of finding in its own box, fixable and listed together (the owner, 10-23: "in their own clearly
    // identified boxes … borders you can see but looks premium"); the engine sorts the groups by it
    if (!g.cat) { root.appendChild(card); return; }
    if (!cat || cat.name !== g.cat) {
      cat = { name: g.cat, box: el("div", "_fc_cat"), n: 0 };
      var ct = el("div", "_fc_cat_t");
      ct.appendChild(el("span", null, g.cat));
      cat.cnt = ct.appendChild(el("span", "_fc_cat_n"));
      cat.box.appendChild(ct);
      root.appendChild(cat.box);
    }
    cat.n += n;
    cat.cnt.textContent = cat.n ? cat.n + " place" + (cat.n === 1 ? "" : "s") : "";
    cat.box.appendChild(card);
  });
  // the Fix bar: what's ticked, and whether Word tracks it (their drafts: on — Option A)
  var bar = el("div", "_fc_fixbar");
  var tr = el("label", "_fc_track");
  var tc = el("input"); tc.type = "checkbox"; tc.checked = !!opts.track; tc.onclick = call("onTrack");
  tr.appendChild(tc);
  tr.appendChild(el("span", null, opts.track ? "Tracked — each fix shows as “Formatted” (their draft)" : "Not tracked — your own draft or a template"));
  bar.appendChild(tr);
  var fb = button(total ? "Fix " + total + " place" + (total === 1 ? "" : "s") : "Tick what to fix", opts.onFix, "_fc_fix");
  fb.disabled = !total || !!opts.fixing;
  bar.appendChild(fb);
  root.appendChild(bar);
  var acts = el("div", "_fc_acts");
  acts.appendChild(button("Check again", opts.onAgain));
  acts.appendChild(button("Back", opts.onBack));
  root.appendChild(acts);
  return root;
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["format_check"];
  var fns = (bundle && bundle._eliEngineFns) || {};
  var find = fns.fcFindings, placesOf = fns.fcPlaces;
  var render = bundle && bundle._eliViewFns && bundle._eliViewFns.renderFormatCheck;
  if (!find || !placesOf || !render) { eli.log.event("tool", "format_check_init_missing_fns", { find: !!find, places: !!placesOf, render: !!render }); return; }
  var CHUNK = 15;   // places a Word visit (each visit two or three syncs)
  var state = { result: null, paras: [], busy: false, fixing: false, error: "", open: {}, tick: {}, off: {}, pick: {}, track: true, trackSet: false, done: null };

  function places(g) { return placesOf(g, state.pick[g.key], state.paras); }
  function paint() {
    var node = render({ result: state.result, busy: state.busy, fixing: state.fixing, error: state.error, open: state.open,
      tick: state.tick, off: state.off, pick: state.pick, track: state.track, done: state.done, places: places,
      onGo: go, onToggle: function (k) { state.open[k] = !state.open[k]; paint(); }, onAgain: function () { state.done = null; run(); },
      onTick: function (k) { state.tick[k] = !state.tick[k]; paint(); }, houseOpen: state.houseOpen, onHouse: function (o) { state.houseOpen = o; },
      onPlace: function (k, n) { var o = state.off[k] = state.off[k] || {}; o[n] = !o[n]; paint(); },
      onPick: function (k, v) { state.pick[k] = state.pick[k] === v ? null : v; state.off[k] = {}; paint(); },
      onTrack: function () { state.track = !state.track; state.trackSet = true; paint(); },
      onFix: fix,
      onBack: function () { if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome(); } });
    var prev = document.querySelector("._fc_root");
    if (prev && prev.parentNode) { prev.parentNode.replaceChild(node, prev); return; }
    var out = eli.ui.claimOutput();
    if (!out) { if (typeof showToast === "function") showToast("Format Check couldn't find the panel.", "err"); return; }
    out.appendChild(node);
  }
  // doc_style's reading with its input (the paragraphs, terms and label looks it measured), then the findings.
  function run() {
    state.busy = true; state.error = ""; paint();
    var t0 = Date.now();
    return Promise.resolve(eli.tools.ensureLoaded("doc_style")).then(function () {
      var read = eli.get && eli.get("doc_style", "read");
      if (typeof read !== "function") throw new Error("ELI's document-style reader isn't installed.");
      return read({ withInput: true });
    }).then(function (a) {
      if (!a || !a.input) throw new Error("This version of ELI's document-style reader can't share what it read — update ELI's tools, then check again.");
      var r = find(a);
      state.result = r;
      state.paras = a.input.paragraphs || [];
      state.tick = {}; state.off = {}; state.pick = {};
      // Option A: tracked unless it's a template (its fields: our own paper) — the user's switch wins once moved
      if (!state.trackSet) state.track = !state.paras.some(function (p) { return /\{\{|\[\[/.test(String((p && p.text) || "")); });
      eli.log.event("tool", "format_check_run", { groups: r.groups.length, places: r.groups.reduce(function (s, g) { return s + g.count; }, 0), paragraphs: r.checked.paragraphs, ms: Date.now() - t0 });
    }).catch(function (e) {
      state.error = "Format Check couldn't read the document: " + String((e && e.message) || e);
    }).then(function () { state.busy = false; paint(); });
  }
  // The places ticked: each paragraph by its index bookmark, through ELI Writer's formatFix, CHUNK at a time; then the
  // document checked again, with what was fixed and what was left as it was (and why) on top.
  function fix() {
    var todo = [];
    (state.result ? state.result.groups : []).forEach(function (g) {
      if (!state.tick[g.key]) return;
      places(g).forEach(function (x, k) { if (!x.nofix && !(state.off[g.key] || {})[k]) todo.push(x); });
    });
    if (!todo.length || state.fixing) return;
    state.fixing = true; state.busy = true; paint();
    var t0 = Date.now(), left = [], ok = 0, tracked = state.track;
    // [TEXT-FIX] the formatting first (it changes no word), then each paragraph's text changes together — one place a
    // paragraph, so a second change there isn't refused as "changed since the check"
    var fmt = todo.filter(function (x) { return x.fix.kind !== "text"; }), txt = {}, order = [];
    todo.forEach(function (x) {
      if (x.fix.kind !== "text") return;
      if (!txt[x.i]) { txt[x.i] = { i: x.i, edits: [], xs: [] }; order.push(x.i); }
      x.edits.forEach(function (e) { if (!txt[x.i].edits.some(function (o) { return e.at < o.at + Math.max(1, o.len) && o.at < e.at + Math.max(1, e.len); })) txt[x.i].edits.push(e); });
      txt[x.i].xs.push(x);
    });
    var pass = function (fnName, items, place, count) {
      var f = eli.get && eli.get("writer", fnName);
      if (!items.length) return Promise.resolve();
      if (typeof f !== "function") { items.forEach(function (d) { left.push({ snippet: d.snippet, why: "ELI Writer needs an update for this fix" }); }); return Promise.resolve(); }
      return eli.host.readStructuralMap({ prefix: "ELI_IDX_" }).then(function (map) {
        var by = (map && map.byParagraphIdx) || {}, list = [];
        items.forEach(function (d, n) {
          var row = by[d.i];
          if (!row || !row.anchor) { left.push({ snippet: d.snippet, why: "its place wasn't found" }); return; }
          list.push({ d: d, place: Object.assign({ id: fnName + n, anchor: row.anchor, text: (state.paras[d.i] || {}).text }, place(d)) });
        });
        var chunks = [];
        for (var c = 0; c < list.length; c += CHUNK) chunks.push(list.slice(c, c + CHUNK));
        return chunks.reduce(function (p, ch) {
          return p.then(function () {
            return eli.host.runRaw("format_check:fix", function (ctx) { return f(ctx, ch.map(function (x) { return x.place; }), { track: tracked }); }).then(function (res) {
              (res || []).forEach(function (r0, k) { count(ch[k].d, r0 || { ok: false, why: "not written" }); });
            });
          });
        }, Promise.resolve());
      });
    };
    Promise.resolve(eli.tools.ensureLoaded("eli_writer")).then(function () {
      return pass("formatFix", fmt, function (x) { return { at: x.at, within: x.within, fix: x.fix }; }, function (x, r0) {
        if (r0.ok) ok++; else left.push({ snippet: x.snippet, why: r0.why || "not written" });
      });
    }).then(function () {
      var paras = order.map(function (i) { return { i: i, snippet: txt[i].xs[0].snippet, edits: txt[i].edits, xs: txt[i].xs }; });
      return pass("textFix", paras, function (d) { return { edits: d.edits }; }, function (d, r0) {
        if (r0.ok) ok += d.xs.length; else left.push({ snippet: d.snippet, why: r0.why || "not written" });
        if (r0.ok && r0.skipped) left.push({ snippet: d.snippet, why: r0.skipped === 1 ? "a change inside a template field left as is" : r0.skipped + " changes inside template fields (or not found as they were) left as is" });
      });
    }).then(function () {
      state.done = { ok: ok, left: left, tracked: tracked };
      eli.log.event("tool", "format_check_fix", { places: todo.length, ok: ok, left: left.length, tracked: tracked, ms: Date.now() - t0 });
    }, function (e) {
      state.done = { ok: ok, left: left.concat([{ snippet: "", why: "Format Check stopped: " + String((e && e.message) || e) }]), tracked: tracked };
    }).then(function () { state.fixing = false; return run(); });
  }
  // A place: its paragraph selected in Word (the structural map's bookmark for it).
  function go(i) {
    if (!eli.host || typeof eli.host.readStructuralMap !== "function") return;
    return eli.host.readStructuralMap({ prefix: "ELI_IDX_" }).then(function (map) {
      var row = map && map.byParagraphIdx && map.byParagraphIdx[i];
      if (!row || !row.anchor) return;
      return eli.host.runRaw("format_check:go", function (ctx) {
        var r = ctx.document.getBookmarkRangeOrNullObject(row.anchor);
        r.load("isNullObject");
        return ctx.sync().then(function () { if (!r.isNullObject) { r.select(); return ctx.sync(); } });
      });
    }).catch(function () {});
  }
  eli.register({ tile: { app_format_check: function () { state.open = {}; state.done = null; state.trackSet = false; run(); } } });
}

jsonTools.css:
/* tools/format_check/style.css — Format Check's panel ([FMT-CHECK]): light in both themes, one gold accent. */
/* its own light surface down to the bottom of the pane (#output is a transparent column over the dark dashboard: the owner saw black under a short list) */
._fc_root { background: #f8fafc; color: #0f1f3d; padding: 0 14px 18px; font: 14px/1.45 "Segoe UI", system-ui, sans-serif; min-height: 100vh; flex: 1 0 auto; box-sizing: border-box; }
.beta-ui-active .output-area:has(> ._fc_root), .output-area:has(> ._fc_root) { background: #f8fafc !important; }
