._fc_card_top { display: flex; align-items: center; gap: 8px; padding: 10px 12px 2px; }
._fc_card_tb { display: flex; flex: 1; align-items: baseline; gap: 10px; padding: 0; background: none; border: 0; text-align: left; cursor: pointer; color: inherit; font: inherit; }
._fc_tick, ._fc_ptick { flex: none; width: 15px; height: 15px; margin: 0; accent-color: #c9a227; cursor: pointer; }
._fc_card._fc_ticked { border-left-color: #0d47a1; }
._fc_item { display: flex; align-items: flex-start; gap: 8px; padding: 6px 12px; }
