._fc_go { flex: 1; display: block; text-align: left; padding: 0; background: none; border: 0; cursor: pointer; color: inherit; font: inherit; }
._fc_ba { display: inline-flex; flex-wrap: wrap; align-items: baseline; gap: 0 6px; max-width: 100%; margin-right: 8px; padding: 0 6px; background: #fdf6e3; font-size: 12px; }
._fc_ba > span { white-space: nowrap; }
._fc_from { color: #7a5d0b; }
._fc_to { color: #14532d; font-weight: 600; }
._fc_arrow { color: #94a3b8; }
._fc_look { font: 13px/1.4 Georgia, serif; color: #0f1f3d; }
._fc_nofix ._fc_ba { opacity: .55; }
._fc_why { display: block; margin-top: 2px; color: #64748b; font-size: 11.5px; font-style: italic; }
._fc_choices { padding: 0 12px 10px; }
._fc_choices_t { color: #334155; font-size: 12.5px; margin-bottom: 5px; }
._fc_choice { display: flex; width: 100%; align-items: baseline; gap: 8px; margin-bottom: 4px; padding: 6px 9px; background: linear-gradient(180deg, #ffffff 0%, #eef2f6 100%); border: 1px solid #cbd5e1; cursor: pointer; text-align: left; }
._fc_choice:hover { border-color: #c9a227; }
._fc_choice._fc_picked { border-color: #c9a227; box-shadow: inset 3px 0 0 #c9a227; background: #fdf8ea; }
._fc_choice_n { color: #64748b; font-size: 11.5px; }
._fc_fixbar { position: sticky; bottom: 0; display: flex; align-items: center; gap: 10px; margin: 14px -14px 0; padding: 10px 14px; background: #fff; border-top: 2px solid #c9a227; box-shadow: 0 -2px 6px rgba(15, 31, 58, .08); }
._fc_track { flex: 1; display: flex; align-items: center; gap: 7px; color: #334155; font-size: 12px; cursor: pointer; }
._fc_track input { accent-color: #c9a227; }
._fc_fix { padding: 8px 14px; color: #fff; border: 1px solid #0d47a1; background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%); font: 600 12.5px/1 "Segoe UI", system-ui, sans-serif; cursor: pointer; }
._fc_fix:disabled { color: #64748b; border-color: #cbd5e1; background: linear-gradient(180deg, #ffffff 0%, #e8edf2 100%); cursor: default; }
._fc_done { margin: 0 0 12px; padding: 9px 11px; background: #f0fdf4; border: 1px solid #bbf7d0; border-left: 3px solid #15803d; }
._fc_done._fc_done_some { background: #fffbeb; border-color: #fde68a; border-left-color: #c9a227; }
._fc_done_t { font-weight: 600; color: #0f1f3d; }
._fc_done_l { margin-top: 3px; color: #475569; font-size: 12px; }
._fc_plain { display: block; width: 100%; text-align: left; background: none; border: 0; cursor: pointer; color: inherit; font: inherit; }
/* [FC-LEDGER] the owner's pick B (10-23, Iris): quiet and editorial — hairline rows, Georgia counts, gold-caps section
   titles between rules. Overrides the rules above. (The navy band stays flush to the top: padding-top 0.) */
._fc_root { background: #fff; padding: 0 14px 0; }
.beta-ui-active .output-area:has(> ._fc_root), .output-area:has(> ._fc_root) { background: #fff !important; }
._fc_head { border-bottom: 0; text-align: center; margin-bottom: 10px; }
._fc_head::after { content: ""; display: block; height: 1px; margin-top: 12px; background: linear-gradient(90deg, transparent, #c9a227, transparent); }
._fc_title { font: 22px/1.1 Georgia, serif; }
._fc_sub { font-size: 11.5px; }
._fc_heads_t, ._fc_sect { display: flex; align-items: center; gap: 10px; font: 700 9px/1 "Segoe UI", system-ui, sans-serif; letter-spacing: .2em; text-transform: uppercase; color: #8a6a0c; margin: 6px 0 8px; }
._fc_heads_t::before, ._fc_heads_t::after, ._fc_sect::before, ._fc_sect::after { content: ""; flex: 1; height: 1px; background: rgba(201, 162, 39, .55); }
._fc_heads_l { display: flex; gap: 8px; font: 12.5px/1.5 "Segoe UI", system-ui, sans-serif; padding: 2px 0; }
._fc_lv { flex: none; width: 22px; font: italic 13px/1.4 Georgia, serif; color: #8a6a0c; }
._fc_verdict { text-align: center; font: italic 16px/1.3 Georgia, serif; }
._fc_checked { text-align: center; }
._fc_card { border: 0; border-top: 1px solid #e3e8ef; margin: 0; background: none; }
._fc_card:last-of-type { border-bottom: 1px solid #e3e8ef; }
._fc_card_top { padding: 11px 2px 2px; }
._fc_card_t { font: 16px/1.2 Georgia, serif; font-weight: 400; }
._fc_card_n { border: 0; padding: 0; font: 18px/1 Georgia, serif; color: #8a6a0c; }
._fc_usual { padding: 0 2px 10px 26px; }
._fc_list { border: 0; margin: 0 0 10px 26px; border-left: 1px solid #c9a227; padding: 0; }
._fc_item { padding: 6px 10px; }
._fc_lo ._fc_card_t { color: #3d4f66; }
._fc_lo ._fc_list { border-left: 1px dashed #b0bec5; }
._fc_lo ._fc_card_n { color: #5b6b85; }
._fc_lotag { display: inline-flex; align-items: center; font: 700 8.5px/1 "Segoe UI", system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: #5b6b85; border: 1px solid #c3ccd8; padding: 3px 6px; background: #f5f7fa; }
._fc_lonote { padding: 0 12px 9px 26px; font-size: 11.5px; color: #5b6b85; }
/* square tick boxes: navy with a gold tick when on */
._fc_tick, ._fc_ptick, ._fc_track input { appearance: none; -webkit-appearance: none; width: 16px; height: 16px; margin: 0; border: 1.5px solid #c9a227; background: #fff; display: inline-grid; place-items: center; flex: none; cursor: pointer; }
._fc_ptick { width: 14px; height: 14px; }
._fc_tick:checked, ._fc_ptick:checked, ._fc_track input:checked { background: #13254a; border-color: #13254a; box-shadow: 0 0 0 2px #f3e3a6; }
._fc_tick:checked::after, ._fc_ptick:checked::after, ._fc_track input:checked::after { content: ""; width: 7px; height: 4px; border-left: 2px solid #f2d866; border-bottom: 2px solid #f2d866; transform: translateY(-1px) rotate(-45deg); }
