._fc_ba { display: flex; background: none; padding: 0; margin: 0 0 3px; gap: 0 7px; font-size: 12px; }
._fc_from { color: #b42318; text-decoration: line-through; text-decoration-color: rgba(180, 35, 24, .6); }
