._fc_arrow { color: #c9a227; }
._fc_snip { display: block; font: italic 13px/1.4 Georgia, serif; color: #3d4f66; }
._fc_found { display: block; background: none; padding: 0; margin: 0 0 2px; color: #8a6a0c; font: 700 10px/1.3 "Segoe UI", system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; }
._fc_go, ._fc_plain { position: relative; padding-right: 18px; }
._fc_go::after, ._fc_plain::after { content: "›"; position: absolute; right: 0; top: 50%; transform: translateY(-50%); color: #c9a227; font: 300 20px/1 "Segoe UI", system-ui, sans-serif; }
