._fc_acts { margin: 0 -14px; padding: 10px 14px 14px; background: #f5f7fa; }
._fc_acts ._fc_btn { flex: 1; }
._fc_done, ._fc_done._fc_done_some { text-align: center; background: none; border: 0; border-top: 1px solid #c9a227; border-bottom: 1px solid #c9a227; padding: 8px 0; }
._fc_done_t { font: italic 15px/1.3 Georgia, serif; color: #15803d; }
/* [FC-CATS] each kind of finding in its own box: a navy hairline, a gold rule on top, square corners, gold-caps title */
._fc_cat { margin: 0 0 12px; border: 1px solid rgba(19, 37, 74, .38); border-top: 2px solid #c9a227; background: #fff; }
._fc_cat_t { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding: 9px 12px 7px; border-bottom: 1px solid #f0e6c8; font: 700 9.5px/1 "Segoe UI", system-ui, sans-serif; letter-spacing: .18em; text-transform: uppercase; color: #8a6a0c; }
._fc_cat_n { font: italic 12px/1 Georgia, serif; letter-spacing: 0; text-transform: none; color: #5b6b85; }
._fc_cat ._fc_card { padding: 0 10px; border-top: 1px solid #e9edf3; }
._fc_cat ._fc_cat_t + ._fc_card { border-top: 0; }
._fc_cat ._fc_card:last-of-type { border-bottom: 0; }
/* [TEMPLATE] a template, said on top */
._fc_tpl { margin: 0 0 12px; padding: 7px 11px; border: 1px solid rgba(19, 37, 74, .38); border-left: 3px solid #13254a; font: 12px/1.4 "Segoe UI", system-ui, sans-serif; color: #0f1f3d; }
._fc_tpl b { color: #8a6a0c; font-weight: 700; }
/* [HOUSE-STYLE] the document's house style on top, folded — for information, nothing to fix */
._fc_house { margin: 2px 0 10px; }
._fc_house > summary { cursor: pointer; list-style: none; }
._fc_house > summary::-webkit-details-marker { display: none; }
._fc_house_c { flex: none !important; display: inline-block; font-size: 9px; transition: transform .15s ease; }
._fc_house[open] ._fc_house_c { transform: rotate(90deg); }
._fc_house_k { text-align: center; font-size: 11.5px; font-style: italic; color: #5b6b85; margin: 0 0 6px; }
._fc_house_r { display: flex; gap: 8px; padding: 3px 0; border-top: 1px solid #f1f4f8; font: 12.5px/1.45 "Segoe UI", system-ui, sans-serif; }
._fc_house_l { flex: none; width: 104px; color: #8a6a0c; font-size: 11.5px; font-weight: 600; }
._fc_house_v { flex: 1; color: #0f1f3d; }
._fc_house_hd { color: #8a6a0c; font-size: 11.5px; font-weight: 600; }
